    internal sealed class CodeTemplateEditor : Form {
        internal readonly TextBox NameField=Ui.TextBox(),ExtensionField=Ui.TextBox(),InstructionsField=Ui.TextBox(),BodyField=Ui.TextBox(true);
        internal readonly ComboBox BaseField=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};
        internal readonly CheckBox CaseField=new CheckBox{Text="Distingui maiuscole e minuscole nei nomi generati",AutoSize=true};
        internal readonly Label Status=Ui.Label("",9.5f,Ui.Muted);internal readonly FlowButton SaveButton,PreviewButton,DiscardButton,CloseButton;
        internal readonly Label BodyLabel=Ui.Label("MODELLO · usa {{ source }} per il programma completo",9.5f,Ui.Muted,true);
