            AddField(fields,initial.Base=="flowgorithm"?"Nome in libreria":"Nome",NameField,0);AddField(fields,"Generatore base",BaseField,1);AddField(fields,"Estensione",ExtensionField,2);AddField(fields,"Come eseguirlo",InstructionsField,3);fields.Controls.Add(CaseField,1,4);CaseField.Dock=DockStyle.Fill;CaseField.AccessibleName=CaseField.Text;
            NameField.MaxLength=80;ExtensionField.MaxLength=16;InstructionsField.MaxLength=1000;BodyField.MaxLength=FlowCodeTemplate.MaxCharacters;BodyField.AcceptsTab=true;BodyField.WordWrap=false;BodyField.ScrollBars=ScrollBars.Both;BodyField.Font=Ui.Mono(10.5f);BodyField.Dock=DockStyle.Fill;BodyField.AccessibleName="Corpo del modello di codice";
            BodyLabel.Dock=DockStyle.Fill;layout.Controls.Add(BodyLabel,0,2);layout.Controls.Add(BodyField,0,3);Status.Dock=DockStyle.Fill;Status.AutoEllipsis=true;layout.Controls.Add(Status,0,4);
