            foreach(var target in FlowSourceTarget.All)BaseField.Items.Add(new Choice(target.Id,target.Name));BaseField.Items.Add(new Choice("custom","Formato libero"));if(initial.Base=="flowgorithm")BaseField.Items.Add(new Choice("flowgorithm","Flowgorithm · .fpgt"));var selected=BaseField.Items.Cast<Choice>().FirstOrDefault(c=>c.Id==initial.Base);if(selected==null){selected=new Choice(initial.Base,"Non disponibile · "+initial.Base);BaseField.Items.Add(selected);}BaseField.SelectedItem=selected;
