        }
        static void AddField(TableLayoutPanel fields,string name,Control control,int row){var label=Ui.Label(name,9.5f,Ui.Muted);label.Dock=DockStyle.Fill;label.TextAlign=ContentAlignment.MiddleLeft;control.Dock=DockStyle.Fill;control.AccessibleName=name;fields.Controls.Add(label,0,row);fields.Controls.Add(control,1,row);}
        internal FlowTemplateDraft CaptureDraft(){return new FlowTemplateDraft(NameField.Text,((Choice)BaseField.SelectedItem).Id,ExtensionField.Text,InstructionsField.Text,BodyField.Text,CaseField.Checked);}
        void ApplyFormat(){bool fpgt=((Choice)BaseField.SelectedItem).Id=="flowgorithm";BaseField.Enabled=!busy&&!fpgt;CaseField.Enabled=!busy&&!fpgt;ExtensionField.ReadOnly=fpgt;BodyLabel.Text=fpgt?"MODELLO .FPGT · modifica le sezioni originali":"MODELLO · usa {{ source }} per il programma completo";if(fpgt)try{var metadata=FlowFpgtSyntax.Parse(BodyField.Text);bool previous=loading;loading=true;try{ExtensionField.Text=metadata.Extension;CaseField.Checked=metadata.CaseSensitive;}finally{loading=previous;}}catch(ArgumentException){/* Incomplete raw text is retained; save/preview report its syntax error. */}}
