        void Queue(Action work,Action done,Action<Exception> failed){var job=pending.ContinueWith(previous=>{try{work();return null;}catch(Exception error){return error;}},TaskScheduler.Default);pending=job;job.ContinueWith(completed=>{if(IsDisposed||!IsHandleCreated)return;try{BeginInvoke(new Action(delegate{if(IsDisposed)return;if(completed.Result==null)done();else{LastError=completed.Result;failed(completed.Result);}}));}catch(InvalidOperationException){/* The window closed; the queued write still completed. */}});}
        void PersistDraft(bool close){if(!dirty){if(close){allowClose=true;Close();}return;}var snapshot=CaptureDraft();string text;try{text=snapshot.Encode();}catch(ArgumentException error){SetStatus(CodeTemplateUi.Problem(error),true);return;}int current=revision;string syntax=null;if(close){Busy(true);SetStatus("Conservo la bozza…",false);}
            Queue(()=>{store.SaveDraft(id,text);ownedDraft=text;try{snapshot.Definition();}catch(ArgumentException error){syntax=CodeTemplateUi.Problem(error);}},()=>{if(close){dirty=false;allowClose=true;Close();return;}if(current!=revision||busy)return;SetStatus(syntax==null?"Bozza conservata · sintassi del modello valida.":"Bozza conservata · "+syntax,syntax!=null);SaveButton.Enabled=PreviewButton.Enabled=syntax==null;ApplyFormat();},error=>{if(close)Busy(false);SetStatus("Bozza non salvata. "+CodeTemplateUi.Problem(error),true);if(close&&FlowMessageDialog.Show(this,"La bozza non è stata salvata. Vuoi chiudere e perdere le ultime modifiche?","Bozza non salvata",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)==DialogResult.Yes){allowClose=true;Close();}});
        }
        internal void SaveModel(){if(busy)return;FlowTemplateDraft snapshot=CaptureDraft();FlowCodeTemplate definition;string draft;try{definition=snapshot.Definition();draft=snapshot.Encode();}catch(ArgumentException error){SetStatus(CodeTemplateUi.Problem(error),true);return;}debounce.Stop();Busy(true);SetStatus("Salvo il modello…",false);FlowTemplateStore.Entry result=null;string warning=null;
